-- ENVISION Ledger Supabase schema; run once in SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now());
create or replace function public.bootstrap_profile() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into public.profiles(id,email,role) values(new.id,new.email,'user') on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created_profile on auth.users;
create trigger on_auth_user_created_profile after insert on auth.users for each row execute procedure public.bootstrap_profile();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create table if not exists public.company_settings(id integer primary key default 1 check(id=1),company_name text not null default 'ENVISION',tagline text not null default 'Where Vision Becomes Reality.',business_address text,email text,phone text,gstin text,logo_url text,theme_color text not null default '#2563EB',invoice_prefix text not null default 'ENV-',next_invoice_number integer not null default 1,currency text not null default 'INR',paper_size text not null default 'A4',print_font text not null default 'Arial',invoice_footer text,show_logo boolean not null default true,show_gstin boolean not null default true,updated_at timestamptz not null default now());
insert into public.company_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),name text not null,company text,email text,phone text,address text,monthly_fee numeric(12,2) not null default 0 check(monthly_fee>=0),contract_start date,contract_end date,status text not null default 'active' check(status in('active','paused','completed')),whatsapp_opt_in boolean not null default false,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(contract_start is null or contract_end is null or contract_end>=contract_start));
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id) on delete set null,name text not null,monthly_fee numeric(12,2) not null default 0 check(monthly_fee>=0),tax_rate numeric(6,3) not null default 0 check(tax_rate between 0 and 100),contract_start date not null,contract_end date not null,payment_due_days integer not null default 7 check(payment_due_days between 0 and 180),status text not null default 'active' check(status in('active','paused','completed')),auto_invoice boolean not null default true,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(contract_end>=contract_start));
create table if not exists public.invoices(id uuid primary key default gen_random_uuid(),invoice_number text not null unique,client_id uuid references public.clients(id) on delete set null,client_name_snapshot text not null,project_id uuid references public.projects(id) on delete set null,billing_period date,issue_date date not null default current_date,due_date date,status text not null default 'issued' check(status in('draft','issued','partially_paid','paid','overdue','cancelled')),items jsonb not null default '[]'::jsonb,subtotal numeric(12,2) not null default 0 check(subtotal>=0),tax_rate numeric(6,3) not null default 0,tax_amount numeric(12,2) not null default 0,total numeric(12,2) not null default 0 check(total>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,billing_period));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,amount numeric(12,2) not null check(amount>0),paid_on date not null default current_date,method text,reference text,notes text,created_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),client_id uuid references public.clients(id) on delete set null,client_name_snapshot text,project_id uuid references public.projects(id) on delete set null,description text not null,category text,amount numeric(12,2) not null check(amount>=0),expense_date date not null default current_date,payment_method text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.reminder_logs(id uuid primary key default gen_random_uuid(),invoice_id uuid references public.invoices(id) on delete set null,client_id uuid references public.clients(id) on delete set null,channel text not null,status text not null,message text,provider_response jsonb,created_at timestamptz not null default now());
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),actor_id uuid,action text not null,entity text not null,entity_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists projects_client_contract_idx on public.projects(client_id,contract_start,contract_end);
create index if not exists invoices_client_date_idx on public.invoices(client_id,issue_date desc);
create index if not exists invoices_due_idx on public.invoices(due_date) where status not in('paid','cancelled');
create index if not exists expenses_client_date_idx on public.expenses(client_id,expense_date desc);
create index if not exists payments_invoice_date_idx on public.payments(invoice_id,paid_on desc);
do $$ declare t text; begin foreach t in array array['company_settings','clients','projects','invoices','payments','expenses','reminder_logs','audit_events'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('drop policy if exists admin_all on public.%I',t);
 execute format('create policy admin_all on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',t);
end loop; end $$;
alter table public.profiles enable row level security;
drop policy if exists profile_self_read on public.profiles;
create policy profile_self_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
drop policy if exists admin_manage_profiles on public.profiles;
create policy admin_manage_profiles on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['clients','projects','invoices','expenses'] loop execute format('drop trigger if exists touch_updated_at on public.%I',t); execute format('create trigger touch_updated_at before update on public.%I for each row execute procedure public.touch_updated_at()',t); end loop; end $$;
-- After creating your own user in Authentication, grant admin: update public.profiles set role='admin' where email='YOUR_ADMIN_EMAIL';
